// ============================================
// VALIDATION INPUT - MCP Gemini Image
// RFC-014: Extract context fields for tracing
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- Tracing context fields (OPTIONAL - no validation errors) ---
const userId = body.user_id || ctx.user_id || body.userId || '';
const guildId = body.guild_id || ctx.guild_id || '';
const userRequest = body.user_request || ctx.user_request || '';

// --- Operation detection ---
const operation = body.operation || ctx.operation || 'generate';

// --- Operation-specific validation ---
const hasPrompt = !!(body.prompt || ctx.prompt);
const hasSourceImage = !!(body.sourceImage || ctx.sourceImage);
const hasScenePrompt = !!(body.scenePrompt || ctx.scenePrompt);
const hasReferenceImages = !!(body.referenceImages || ctx.referenceImages);

// Validate based on operation
switch (operation) {
  case 'generate':
    if (!hasPrompt) {
      errors.push('prompt requis pour operation generate');
    }
    break;

  case 'extractCharacter':
  case 'createCharacterSheet':
    if (!hasSourceImage) {
      errors.push('sourceImage requis pour operation ' + operation);
    }
    break;

  case 'composeScene':
    if (!hasScenePrompt) {
      errors.push('scenePrompt requis pour operation composeScene');
    }
    break;

  default:
    // For unknown operations, require at least one input
    if (!hasPrompt && !hasSourceImage && !hasScenePrompt) {
      errors.push('Au moins un input requis: prompt, sourceImage, ou scenePrompt');
    }
}

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest,
    operation: operation
  };
}

// --- Extract all parameters ---
const aspectRatio = body.aspectRatio || ctx.aspectRatio || '16:9';
const outputFormat = body.outputFormat || ctx.outputFormat || 'png';
const model = body.model || ctx.model || 'gemini-2.5-flash-preview-native-audio-dialog';
const includeTextFeedback = body.includeTextFeedback === true || body.includeTextFeedback === 'true';

// GCS upload parameters
const uploadToGcs = body.uploadToGcs === true || body.uploadToGcs === 'true';
const gcsBucket = body.gcsBucket || ctx.gcsBucket || '';
const gcsPathPrefix = body.gcsPathPrefix || ctx.gcsPathPrefix || 'gemini-images';
const signedUrlExpirationHours = body.signedUrlExpirationHours || ctx.signedUrlExpirationHours || 24;

return {
  valid: true,
  operation: operation,
  // Generate params
  prompt: body.prompt || ctx.prompt || '',
  // Extract/Sheet params
  sourceImage: body.sourceImage || ctx.sourceImage || '',
  sourceImageMimeType: body.sourceImageMimeType || ctx.sourceImageMimeType || 'image/png',
  characterDescription: body.characterDescription || ctx.characterDescription || 'the main character',
  views: body.views || ctx.views || ['front', 'back'],
  // Compose params
  referenceImages: body.referenceImages || ctx.referenceImages || [],
  scenePrompt: body.scenePrompt || ctx.scenePrompt || '',
  // Common params
  aspectRatio: aspectRatio,
  outputFormat: outputFormat,
  model: model,
  includeTextFeedback: includeTextFeedback,
  uploadToGcs: uploadToGcs,
  gcsBucket: gcsBucket,
  gcsPathPrefix: gcsPathPrefix,
  signedUrlExpirationHours: signedUrlExpirationHours,
  // Tracing context
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  startTime: Date.now(),
  originalRequest: { ...body }
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'gemini-image',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  operation: input.operation,
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

// ============================================
// FORMAT RESPONSE - MCP Gemini Image
// ============================================

const prevData = $('Validate Input').first().json;
const input = $input.first().json;

const response = {
  success: true,
  operation: input.operation || prevData.operation,
  image: {
    base64: input.imageBase64,
    mimeType: input.mimeType,
    format: input.mimeType ? input.mimeType.split('/')[1] : 'png'
  },
  model: input.model || prevData.model,
  textFeedback: input.textFeedback || null,
  metadata: input.metadata || {},
  user_id: prevData.user_id,
  guild_id: prevData.guild_id,
  user_request: prevData.user_request,
  _trace: {
    service_response: {
      operation: input.operation || prevData.operation,
      model: input.model || prevData.model,
      has_image: !!input.imageBase64,
      has_gcs: !!input.gcs
    },
    provider: 'gemini-image',
    mode: 'success',
    latency_ms: Date.now() - prevData.startTime,
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    user_request: prevData.user_request
  }
};

// Add GCS info if present
if (input.gcs) {
  response.gcs = input.gcs;
}

return response;

